    public function __construct(public string $name, public string $class = 'h-5 w-5') {}

    public function render(): \Closure
    {
        $class = e($this->class);

        /*
         * A closure is returned so the attribute bag (x-show, x-cloak, ::class,
         * aria-*) is available: Blade assigns attributes after render() is
         * called, so they can only be read from the data passed to the closure.
         */
        return function (array $data) use ($class): string {
            $bag = $data['attributes'] ?? null;
            $extra = $bag ? trim((string) $bag->except('class')) : '';
            $extra = $extra === '' ? '' : ' '.$extra;

            if (isset(self::FILLED[$this->name])) {
                $path = self::FILLED[$this->name];

                return "<svg class=\"{$class}\"{$extra} fill=\"currentColor\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"{$path}\"/></svg>";
            }

            $path = self::PATHS[$this->name] ?? self::PATHS['squares'];

            return "<svg class=\"{$class}\"{$extra} fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\" aria-hidden=\"true\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"{$path}\"/></svg>";
        };
    }
